1	import React from 'react';
2	import { chakra, VStack } from '@chakra-ui/react';
3	import { FormattedMessage } from 'react-intl';
4	import { ZimmProductDescription } from 'app/components/ui-kits/atoms/zimmProductDescription';
5	import { ZimmProductStyleCode } from 'app/components/ui-kits/atoms/zimmProductStyleCode';
6	import { isBlankRichText } from 'app/utils/richText';
7	
8	export type DetailsAndCareContentProps = {
9	  /** The product's display name — Figma's "Product Description" section heading. */
10	  displayName: string;
11	  longDescription?: string;
12	  /** `c_careInstructions` — same Business-Manager-authored markup shape as `longDescription`. */
13	  careInstructions?: string;
14	  styleCode?: string;
15	};
16	
17	/*
18	 * No `material` prop yet — the design (Figma node 40001889:38504) shows a "Material" section
19	 * between Product Description and Care, but Tim has confirmed there is no SFCC attribute for it
20	 * yet (`material = TBD`). Omitted entirely rather than shown empty, matching this codebase's
21	 * established graceful-degradation pattern (`ZimmProductDescription`/`ZimmProductStyleCode` both
22	 * render nothing without data) — add it back once the attribute is confirmed.
23	 */
24	
25	/** One `{heading, body}` block, spaced per Figma's 8px heading-to-body / 64px between-sections
26	 *  rhythm (`overrides/app/pages/product-detail/detailsAndCareContent.css.ts`... — no co-located
27	 *  recipe needed here: every value is a direct `var(--zimm-*)` Chakra prop, nothing varies by
28	 *  variant/state, so a recipe would be pure overhead per overrideStyling.md's hierarchy). */
29	const Section = ({ heading, children }: { heading: React.ReactNode; children: React.ReactNode }) => (
30	  <VStack align="stretch" spacing="var(--zimm-scale-xs)" width="100%">
31	    <chakra.h2 textStyle="productNames" color="var(--zimm-color-text-default)" margin={0}>
32	      {heading}
33	    </chakra.h2>
34	    {children}
35	  </VStack>
36	);
37	
38	/**
39	 * SFCC-195 — Details & Care tab content for ZimmPdpDrawer. Presentational: receives product
40	 * data as props (per components.md's container/presentational rule), sourced entirely from
41	 * SFCC attributes via `selectPdpProductInfo` — no Contentful, matching this bucket's confirmed
42	 * sourcing (see the plan doc's "Tab CONTENT model is mixed-source" note).
43	 */
44	export const DetailsAndCareContent = ({
45	  displayName,
46	  longDescription,
47	  careInstructions,
48	  styleCode,
49	}: DetailsAndCareContentProps) => {
50	  return (
51	    <VStack align="stretch" spacing="var(--zimm-scale-4xl)" width="100%">
52	      {!isBlankRichText(longDescription) && (
53	        <Section heading={displayName}>
54	          <ZimmProductDescription description={longDescription} />
55	        </Section>
56	      )}
57	
58	      {!isBlankRichText(careInstructions) && (
59	        <Section heading={<FormattedMessage defaultMessage="Care" id="product_detail.details_and_care.heading.care" />}>
60	          <ZimmProductDescription description={careInstructions} />
61	        </Section>
62	      )}
63	
64	      {/* Renders unconditionally within this stack (not nested under Care) — ZimmProductStyleCode
65	          already returns null with no value, so it must not also disappear just because
66	          c_careInstructions happens to be unpopulated for this product. */}
67	      <ZimmProductStyleCode value={styleCode} />
68	    </VStack>
69	  );
70	};
