1	/**
2	 * Maps a Commerce API product onto the props the PDP's static-information components take.
3	 *
4	 * Extracted from the page so the mapping is unit-testable on its own. Nothing else on the PDP
5	 * ties an external field name to a rendered prop, and a mis-keyed field here does not fail
6	 * loudly: it falls through to `undefined`, the component returns `null`, and the page renders
7	 * a plausible-looking product with one line quietly missing. Neither a Storybook `play`
8	 * (which supplies its own props) nor an axe run can see that.
9	 */
10	
11	/*
12	 * The Commerce SDK's `Product` type does not carry Zimmermann's `c_*` custom attributes, and
13	 * `@salesforce/retail-react-app` ships no types at all. This is the narrow shape this mapping
14	 * actually reads — everything optional, because every one of these fields can be absent on a
15	 * real catalogue product.
16	 */
17	/**
18	 * Shape of `c_tabDescription`/`c_tabDetails` — a rich-text attribute authored with both a
19	 * rendered `markup` (HTML, same shape as `longDescription`) and its plain-text `source`. Only
20	 * `markup` is read below, matching how every other rich-text field on this page is consumed
21	 * (through `app/utils/richText`'s HTML parser, not the plain-text form).
22	 */
23	export type SfccRichTextAttribute = {
24	  markup?: string;
25	  source?: string;
26	};
27	
28	export type PdpSourceProduct = {
29	  id?: string;
30	  name?: string;
31	  longDescription?: string;
32	  /** Master product reference. Present on a variant; absent on a standard product. */
33	  master?: { masterId?: string };
34	  /** Zimmermann custom attribute holding the model's measurements and worn size. */
35	  c_modelFit?: string;
36	  /** Zimmermann custom attribute holding the product's care instructions, authored in Business
37	   *  Manager with the same markup shape as `longDescription` (see `app/utils/richText`). */
38	  c_careInstructions?: string;
39	  /** Colour code (e.g. "GVSCP") — not a display name. */
40	  c_color?: string;
41	  c_colourId?: string;
42	  /** EU Environmental Qualities content — SFCC-266's data source (MuleSoft/AP21). */
43	  c_environmentalNotes?: string;
44	  /** Site preference flag (SFCC-266). The SCAPI hook resolves showEnvironmentalQualities
45	   *  against request.locale server-side and returns the boolean result — true only for
46	   *  EU locales listed in BM. The PWA reads this scalar directly; no locale matching needed. */
47	  c_showEnvironmentalNote?: boolean;
48	  /** Fallback content from the environmentalMessage site preference (SFCC-266).
49	   *  The SCAPI hook resolves the JSON keyed by request.locale and returns the plain string
50	   *  for the current locale. Used when c_environmentalNotes (AP21) is absent. */
51	  c_environmentalMessage?: string;
52	  c_fabricComposition?: string;
53	  /** Customs/tariff Harmonized System code — not a PDP display field. */
54	  c_hsCode?: string;
55	  /** HTML rich text for the "Size & Fit" copy block rendered at the top of the Size Guide tab
56	   *  (SFCC-102). Rendered via ZimmProductDescription alongside the Contentful size guide tables. */
57	  c_sizeFit?: string;
58	  /** Contentful size guide key (e.g. "womens-dresses") — resolved client-side via useSizeGuide
59	   *  to the matching SizeGuideEntry for this product's locale (SFCC-102). */
60	  c_sizeGuide?: string;
61	  c_styleId?: string;
62	  c_styleNumber?: string;
63	  c_stylingNotes?: string;
64	  c_tabDescription?: SfccRichTextAttribute;
65	  c_tabDetails?: SfccRichTextAttribute;
66	  /**
67	   * SFCC-225's custom attribute, pre-sorted by badgePriorityOrder. `productBadgeUrl` is the
68	   * filtered-PLP category URL for that badge (.docs/prd/pdp.md §3); a badge with no URL still
69	   * renders, just non-interactive (see ZimmBadge). ZimmProductBadges caps display at 2
70	   * (SFCC-132, confirmed 2026-09-07) — this mapping does not truncate the list itself.
71	   */
72	  c_productBadges?: Array<{ productBadge?: string; productBadgeUrl?: string }>;
73	};
74	
75	/** The subset of `getPriceData`'s result this mapping needs. */
76	export type PdpSourcePrice = {
77	  currentPrice?: number;
78	  /** True when the variant's selling price is below its list (RRP) price — PRC-09. */
79	  isOnSale?: boolean;
80	  /** The original RRP. Present when `isOnSale` is true. */
81	  listPrice?: number;
82	  /**
83	   * True when `currentPrice` is the minimum across a set of variants rather than a single
84	   * definite price — e.g. a colour-only selection where sizes have different sale prices.
85	   * When true, Was/Now is suppressed: `currentPrice` is not a settled figure and showing a
86	   * definite Was/Now would misrepresent the product's pricing.
87	   */
88	  isRange?: boolean;
89	};
90	
91	/** Formats a bare amount for the storefront. Injected so this module stays free of react-intl. */
92	export type FormatPrice = (amount: number, currency: string) => string;
93	
94	export type PdpProductInfo = {
95	  name: string;
96	  /** Active selling price (the "Now" price when on sale). */
97	  price: string;
98	  /** Original RRP. Present only when the product is on sale (PRC-09). */
99	  wasPrice?: string;
100	  description?: string;
101	  modelInfo?: string;
102	  careInstructions?: string;
103	  styleCode?: string;
104	  colour?: string;
105	  colourId?: string;
106	  environmentalNotes?: string;
107	  showEnvironmentalNote?: boolean;
108	  environmentalMessage?: string;
109	  fabricComposition?: string;
110	  hsCode?: string;
111	  sizeFit?: string;
112	  sizeGuide?: string;
113	  styleId?: string;
114	  styleNumber?: string;
115	  stylingNotes?: string;
116	  tabDescription?: string;
117	  tabDetails?: string;
118	  /** All applicable badges with their PLP hrefs, in priority order (e.g. Runway, then
119	   *  Exclusive). Absent when none apply. ZimmProductBadges caps display at 2. Shape matches
120	   *  ZimmProductBadges' own ProductBadge type structurally — not imported, same as
121	   *  buildRelatedSwatches below and ZimmColourSwatchGroup's ZimmColourSwatchValue. */
122	  badges?: Array<{ label: string; href?: string }>;
123	};
124	
125	/** One item in the `c_relatedSwatches` array resolved by the SCAPI hook (SFCC-708). */
126	export type RelatedSwatch = {
127	  masterProductID: string;
128	  colourValue: string;
129	  displayName: string;
130	  swatchImageURL: string;
131	};
132	
133	/**
134	 * @param product - The resolved product (variant when one is selected, master otherwise).
135	 * @param priceData - `getPriceData(...)`'s result, as ProductView computes it.
136	 * @param currency - The storefront's active currency code.
137	 * @param formatPrice - Currency formatter, normally `intl.formatNumber`.
138	 * @returns Props for the static-information components, or `null` while the product loads.
139	 */
140	export const selectPdpProductInfo = (
141	  product: PdpSourceProduct | undefined | null,
142	  priceData: PdpSourcePrice | undefined | null,
143	  currency: string,
144	  formatPrice: FormatPrice,
145	): PdpProductInfo | null => {
146	  if (!product?.name) return null;
147	
148	  return {
149	    name: product.name,
150	    price: typeof priceData?.currentPrice === 'number' ? formatPrice(priceData.currentPrice, currency) : '',
151	    // PRC-09: expose the original RRP as wasPrice only when the item is genuinely on sale,
152	    // the price is a settled definite figure (not a range minimum), and the list price is a
153	    // real number. When `isRange` is true, `currentPrice` is the cheapest across a set of
154	    // variants — showing a definite Was/Now would misrepresent the price for other variants.
155	    // The Was/Now atoms branch on wasPrice's presence; when absent ZimmProductPrice renders
156	    // the standard single-price treatment.
157	    wasPrice:
158	      priceData?.isOnSale &&
159	      !priceData.isRange &&
160	      typeof priceData.currentPrice === 'number' &&
161	      typeof priceData.listPrice === 'number'
162	        ? formatPrice(priceData.listPrice, currency)
163	        : undefined,
164	    description: product.longDescription,
165	    modelInfo: product.c_modelFit,
166	    careInstructions: product.c_careInstructions,
167	    // The style code shoppers see is the *master* style number. `product.id` is the variant
168	    // SKU once a size is selected, so reading it would silently show a different value after
169	    // the first swatch click. Standard products have no master, and there `id` is correct.
170	    // Unchanged by the c_styleNumber addition below: Tim hasn't confirmed this should switch to
171	    // that attribute, only that c_styleNumber should be mapped and available.
172	    styleCode: product.master?.masterId ?? product.id,
173	    colour: product.c_color,
174	    colourId: product.c_colourId,
175	    environmentalNotes: product.c_environmentalNotes,
176	    showEnvironmentalNote: product.c_showEnvironmentalNote,
177	    environmentalMessage: product.c_environmentalMessage,
178	    fabricComposition: product.c_fabricComposition,
179	    hsCode: product.c_hsCode,
180	    sizeFit: product.c_sizeFit,
181	    sizeGuide: product.c_sizeGuide,
182	    styleId: product.c_styleId,
183	    styleNumber: product.c_styleNumber,
184	    stylingNotes: product.c_stylingNotes,
185	    tabDescription: product.c_tabDescription?.markup,
186	    tabDetails: product.c_tabDetails?.markup,
187	    // SCAPI pre-sorts c_productBadges by badgePriorityOrder and filters to the active region/locale,
188	    // so the frontend just renders them in the order they arrive. href-safety (isSafeHref) is
189	    // enforced at render time by ZimmBadge, not duplicated here.
190	    badges: product.c_productBadges
191	      ?.filter((b): b is { productBadge: string; productBadgeUrl?: string } => Boolean(b.productBadge))
192	      .map((b) => ({ label: b.productBadge, href: b.productBadgeUrl })),
193	  };
194	};
195	
196	/**
197	 * Predicate injected into `selectEnvQualitiesContent` so the module stays free of
198	 * external imports and the logic is testable with a plain function.
199	 */
200	export type IsBlankRichText = (markup: string | undefined | null) => boolean;
201	
202	/**
203	 * Returns the content string the Environmental Qualities drawer tab should display,
204	 * or `undefined` when the tab must not appear.
205	 *
206	 * The tab is suppressed entirely when either:
207	 * - `showEnvironmentalNote` is not `true` (the SCAPI hook resolved the site-pref flag
208	 *   for the request locale and it is not an EU locale), or
209	 * - both `environmentalNotes` (AP21 copy) and `environmentalMessage` (site pref
210	 *   fallback) are blank after stripping HTML tags.
211	 *
212	 * Priority: AP21 notes (`environmentalNotes`) first; site-pref fallback
213	 * (`environmentalMessage`) second. Returns the first non-blank string found.
214	 *
215	 * @param info - Mapped product info (result of `selectPdpProductInfo`), or `null` while
216	 *   the product is loading.
217	 * @param isBlank - Predicate returning `true` when a markup string is empty after
218	 *   stripping tags (inject `isBlankRichText` from `app/utils/richText`).
219	 * @returns The content string, or `undefined` when the tab should not render.
220	 */
221	export const selectEnvQualitiesContent = (
222	  info: PdpProductInfo | null,
223	  isBlank: IsBlankRichText,
224	): string | undefined => {
225	  if (info?.showEnvironmentalNote !== true) return undefined;
226	  if (!isBlank(info.environmentalNotes)) return info.environmentalNotes;
227	  if (!isBlank(info.environmentalMessage)) return info.environmentalMessage;
228	  return undefined;
229	};
230	
231	/**
232	 * Maps SCAPI `c_relatedSwatches` items onto ZimmColourSwatchGroup-compatible swatch values.
233	 *
234	 * `urlBuilder` and `colourAttrId` are injected so this module stays dependency-free and
235	 * testable without a router context — the same pattern `selectPdpProductInfo` uses for
236	 * `formatPrice`.
237	 *
238	 * @param rawSwatches - The raw `c_relatedSwatches` array, pre-filtered by the SCAPI hook.
239	 * @param urlBuilder - Returns the base product URL for a given ID (e.g. `productUrlBuilder`).
240	 * @param colourAttrId - URL query-param key for the colour value (e.g. `'color'`).
241	 * @returns ZimmColourSwatchGroup-compatible swatch values with `forceReload: true`.
242	 */
243	export const buildRelatedSwatches = (
244	  rawSwatches: RelatedSwatch[],
245	  urlBuilder: (params: { id: string }) => string,
246	  colourAttrId: string,
247	) =>
248	  rawSwatches.map((item) => ({
249	    value: item.masterProductID,
250	    name: item.displayName,
251	    imageUrl: item.swatchImageURL,
252	    href: `${urlBuilder({ id: item.masterProductID })}?${colourAttrId}=${encodeURIComponent(item.colourValue)}`,
253	    orderable: true as const,
254	    forceReload: true as const,
255	  }));
