module.exports = {
  id: 'link',
  name: 'Link',
  displayField: 'label',
  description:
    'A single reusable navigation link (label + destination), optionally scoped to one ' +
    'or more storefronts via `regions`. Referenced from navGroup and footerConfig ' +
    'today; designed to be referenced from other content types later (e.g. header nav, ' +
    'mega-menu) without change.',
