/**
 * Generic region-scoping resolution for Contentful entries carrying a `regions`
 * reference field (see overrides/app/types/contentful.ts's RegionEntry / LinkEntry /
 * FooterConfigEntry). Not footer-specific — works against any entry shaped this way.
 *
 * An entry with an omitted or empty `regions` array is the global/default case: it
 * matches every site and is the *least* specific match. An entry scoping `regions` to
 * fewer sites is more specific than one scoping it to more.
 */

type RegionRef = { fields: { siteId: string } };

type RegionAwareEntry = {
  // Index signature deliberately widens this past a TS "weak type" (all-optional, no
  // index signature) — without it, a concrete Contentful entry's `sys: {id, contentType}`
  // shares zero properties with `{updatedAt?}` and fails the generic constraint check below,
  // even though it's exactly the shape this utility exists to accept.
  sys?: { updatedAt?: string; [key: string]: unknown };
  fields: { regions?: ReadonlyArray<RegionRef> };
};

const isEligible = (entry: RegionAwareEntry, siteId: string): boolean => {
  const regions = entry.fields.regions;
  if (!regions || regions.length === 0) return true;
  return regions.some((region) => region.fields.siteId === siteId);
};

/** Fewer regions = more specific. Global/unscoped (empty or omitted) sorts last. */
const specificity = (entry: RegionAwareEntry): number =>
  entry.fields.regions && entry.fields.regions.length > 0 ? entry.fields.regions.length : Infinity;

/**
 * Inclusive filter — every entry eligible for `siteId` is kept, no precedence applied.
 * Use for arrays where multiple non-conflicting regional entries can legitimately
 * coexist in the same rendered list (e.g. links inside a shared navGroup).
 */
export function filterByRegion<T extends RegionAwareEntry>(entries: readonly T[], siteId: string): T[] {
  return entries.filter((entry) => isEligible(entry, siteId));
}

/**
 * Single-winner resolution — picks the most specific entry eligible for `siteId`. Use
 * for a root entry where only one should render (e.g. which footerConfig to use for
 * the current site).
 *
 * A tie between two equally-scoped entries is an editorial mistake the additive-only sync
 * pipeline doesn't prevent (nothing stops two entries both scoping to e.g. exactly
 * ['ZimmermannUS'] — or two unscoped entries, which tie at Infinity). Resolved
 * deterministically by most-recently-updated, then by `sys.id` when those match, rather than
 * by CDA response order — and a console.warn fires on every tie, whichever side wins, so the
 * duplicate entry can be cleaned up. Fires n-1 times for an n-way tie, once per mount.
 */
export function pickMostSpecificByRegion<T extends RegionAwareEntry>(
  candidates: readonly T[],
  siteId: string,
): T | undefined {
  const eligible = filterByRegion(candidates, siteId);

  let best: T | undefined;
  let bestSpecificity = Infinity;

  for (const candidate of eligible) {
    const candidateSpecificity = specificity(candidate);

    if (best === undefined || candidateSpecificity < bestSpecificity) {
      best = candidate;
      bestSpecificity = candidateSpecificity;
      continue;
    }

    if (candidateSpecificity === bestSpecificity) {
      // The warn sits outside the comparison on purpose. It used to live inside the
      // most-recently-updated check, which meant it only fired when the candidate happened to be
      // newer than the incumbent — so a tie already arriving newest-first, or one where both
      // entries share an updatedAt, was resolved silently. The tie itself is the editorial
      // mistake worth surfacing, regardless of which side of it wins.
      console.warn(
        `resolveByRegion: tie between two equally-scoped entries for region "${siteId}" — resolving by most-recently-updated, then by sys.id.`,
      );

      const bestUpdatedAt = best.sys?.updatedAt ?? '';
      const candidateUpdatedAt = candidate.sys?.updatedAt ?? '';
      // `sys.id` breaks a dead heat. Without it, equal (or absent) timestamps left the winner
      // decided by whichever entry the CDA happened to return first — and `getEntries` is called
      // with no `order`, so that isn't stable across requests.
      const bestId = String(best.sys?.id ?? '');
      const candidateId = String(candidate.sys?.id ?? '');
      if (candidateUpdatedAt > bestUpdatedAt || (candidateUpdatedAt === bestUpdatedAt && candidateId < bestId)) {
        best = candidate;
      }
    }
  }

  return best;
}
