    'sizeGuide',
    false,
    CONTENTFUL_FALLBACK_LOCALE,
    keyFilter,
    Boolean(sizeGuideKey),
    3,
  );

  const sizeGuide = useMemo(() => {
    if (!sizeGuideKey || !entries || !localeKey || !defaultKey) return null;

    // For each candidate key group, pick the most region-specific entry eligible for
    // siteId. Guides with no regions (or empty regions) are global fallbacks; guides
    // with regions are valid only when a linked RegionEntry.fields.siteId matches.
    const localeMatches = entries.filter((e) => e.fields.key === localeKey);
    const defaultMatches = entries.filter((e) => e.fields.key === defaultKey);
    const matched =
      pickMostSpecificByRegion(localeMatches, siteId) ?? pickMostSpecificByRegion(defaultMatches, siteId) ?? null;

