import React from 'react';
import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
import { useIntl } from 'react-intl';

const ZIMM_PRODUCT_STYLE_CODE_RECIPE = 'ZimmProductStyleCode';

/*
 * The label is UI copy, so it is a translatable message rather than a literal. `defaultMessage`
 * carries the English inline, which is what makes this work with no `translations/` entry: that
 * directory is Tier 2 (owner Integration/SI Partner) and is populated by the extraction step, so
 * a component cannot add to it. Until extraction runs, every locale renders `defaultMessage`;
 * once it does, the eleven locales pick up their own string with no change here.
 *
 * The id follows the base template's namespace for PDP labels — `product_view.label.quantity`
 * and `product_view.label.variant_type` are its siblings — so a translator finds it with the
 * rest of the PDP copy.
 */
const LABEL_MESSAGE = {
  id: 'product_view.label.style_code',
  defaultMessage: 'Style Code:',
};

type ZimmProductStyleCodeProps = {
  /**
   * The master product's style number. This is the style code shown to shoppers, which is not
   * the same value as the variant `product.id`.
   */
  value?: string;
};

/**
 * Atom — the "Style Code: 7300JS261" line. Renders nothing when no style code is available.
 *
 * The label comes from `react-intl`, not from CMS microcopy and not from a literal. A `uiCopy`
 * lookup is the wrong tool here — `useContentful.ts` requests entries with no `locale`
 * parameter, so it would serve the space default to all eight storefronts regardless of site —
 * but a bare literal is not the remedy for that, it just ships English to all eleven locales
 * instead. `formatMessage` is the base template's own mechanism and is per-locale by
 * construction.
 *
 * components.md exempts `useIntl` from the container/presentational rule: it reads a Provider
 * mounted above the route tree, so calling it from a leaf creates none of the per-page fetch
 * problems that rule exists to prevent. It does *throw* without an `IntlProvider` — the app
 * mounts one in the base `_app`, `.storybook/preview.tsx` mounts one for stories, and
 * `index.test.tsx` wraps its renders for the same reason.
 */
export const ZimmProductStyleCode = ({ value }: ZimmProductStyleCodeProps) => {
  const styles = useMultiStyleConfig(ZIMM_PRODUCT_STYLE_CODE_RECIPE, {});
  // `intl.formatMessage`, not a destructured `{ formatMessage }`: destructuring a method off
  // `useIntl()` trips `@typescript-eslint/unbound-method`, which `staticProductHeader.tsx` has to
  // suppress inline. `product-view/index.tsx` uses this form throughout and needs no suppression.
  const intl = useIntl();
  // Both hooks sit above the guard: an early return before either makes that call conditional,
  // which `react-hooks/rules-of-hooks` reports as an error. Same ordering as the sibling atoms.
  if (!value) return null;

  return (
    <chakra.div __css={styles.root} data-testid="product-style-code">
      <chakra.span __css={styles.label}>{intl.formatMessage(LABEL_MESSAGE)}</chakra.span>
      {/*
        A real space so `textContent` — what a screen reader reads out and what a shopper
        copies — is "Style Code: 8637DS241", matching both composed page designs. It adds no
        visual width: a whitespace-only anonymous flex item is not rendered (CSS Flexbox §4),
        so the 4px `gap` in the recipe remains the only spacing.
      */}{' '}
      <chakra.span __css={styles.value}>{value}</chakra.span>
    </chakra.div>
  );
};

